package com.github.corhen.poisonring;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("poisonring")
public interface PoisonRingConfig extends Config {

    @ConfigItem(
        keyName = "shiftX",
        name = "Shift X",
        description = "Shifts the ring left (negative) or right (positive)",
        position = 1
    )
    default int shiftX() {
        return 1;
    }

    @ConfigItem(
        keyName = "shiftY",
        name = "Shift Y",
        description = "Shifts the ring up (negative) or down (positive)",
        position = 2
    )
    default int shiftY() {
        return 1;
    }

    @ConfigItem(
        keyName = "diameter",
        name = "Diameter",
        description = "Shrinks (negative) or expands (positive) the circle diameter",
        position = 3
    )
    default int diameter() {
        return -1;
    }

    @ConfigItem(
        keyName = "lineThickness",
        name = "Line Thickness",
        description = "Changes the thickness of the ring",
        position = 4
    )
    default int lineThickness() {
        return 2;
    }

    @ConfigItem(
        keyName = "poisonColor",
        name = "Poison Color",
        description = "The color of the ring when poisoned",
        position = 5
    )
    default Color poisonColor() {
        return new Color(0, 255, 0, 255);
    }

    @ConfigItem(
        keyName = "testMode",
        name = "Test Mode",
        description = "Displays the ring for alignment purposes without being poisoned",
        position = 0 // Put it at the very top
    )
    default boolean testMode() {
        return false;
    }

    @ConfigItem(
        keyName = "venomColor",
        name = "Venom Color",
        description = "The color of the ring when venomed",
        position = 6
    )
    default Color venomColor() {
        return new Color(0, 255, 0, 255);
    }
}

package com.github.corhen.poisonring;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.Arc2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.ComponentID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class PoisonRingOverlay extends Overlay {
    private final Client client;
    private final PoisonRingPlugin plugin;
    private final PoisonRingConfig config;

    @Inject
    public PoisonRingOverlay(Client client, PoisonRingPlugin plugin, PoisonRingConfig config) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DETACHED);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!plugin.isPoisoned()) {
            return null;
        }

        Widget healthOrb = client.getWidget(ComponentID.MINIMAP_HEALTH_ORB);
        if (healthOrb == null || healthOrb.isHidden()) {
            return null;
        }

        Rectangle bounds = healthOrb.getBounds();

        int baseOrbX = bounds.x + (bounds.width - bounds.height);
        int baseOrbY = bounds.y;

        int finalX = baseOrbX + config.shiftX();
        int finalY = baseOrbY + config.shiftY();
        int finalDiameter = bounds.height + config.diameter();

        double progress;
        if (config.testMode() && plugin.getTicksUntilDamage() == 0) {
            progress = 0.5; // Show a half-circle in test mode so you can see the arc
        } else {
            progress = (double) plugin.getTicksUntilDamage() / plugin.getPoisonTickRate();
        }

        int startAngle = 90;
        int extent = (int) -(360 * progress); 

        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        graphics.setColor(plugin.isVenom() ? config.venomColor() : config.poisonColor());
        graphics.setStroke(new BasicStroke(config.lineThickness()));

        Arc2D.Double arc = new Arc2D.Double(
            finalX, 
            finalY, 
            finalDiameter, 
            finalDiameter, 
            startAngle, 
            extent, 
            Arc2D.OPEN
        );

        graphics.draw(arc);

        return null;
    }
}

package com.github.corhen.poisonring;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.HitsplatID;
import net.runelite.api.VarPlayer;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "Poison Ring",
    description = "Adds a ring around the HP orb showing time until next poison/venom tick",
    tags = {"poison", "venom", "hp", "orb", "timer", "combat"}
)
public class PoisonRingPlugin extends Plugin {
    @Inject
    private Client client;

    @Inject
    private PoisonRingConfig config;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private PoisonRingOverlay overlay;

    private int poisonValue = 0;
    private int ticksUntilDamage = 0;
    private boolean isVenom = false;

    private static final int POISON_TICK_RATE = 30; 

    @Provides
    PoisonRingConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(PoisonRingConfig.class);
    }

    @Override
    protected void startUp() {
        overlayManager.add(overlay);
        checkPoisonState();
    }

    @Override
    protected void shutDown() {
        overlayManager.remove(overlay);
        poisonValue = 0;
        ticksUntilDamage = 0;
        isVenom = false;
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event) {
        if (event.getVarpId() == VarPlayer.POISON) {
            checkPoisonState();
        }
    }

    private void checkPoisonState() {
        int newValue = client.getVarpValue(VarPlayer.POISON);

        if (newValue <= 0) {
            poisonValue = 0;
            ticksUntilDamage = 0;
            isVenom = false;
        } else {
            if (poisonValue <= 0 || (newValue >= 1000000 && poisonValue < 1000000)) {
                ticksUntilDamage = POISON_TICK_RATE;
            }
            poisonValue = newValue;
            isVenom = newValue >= 1000000;
        }
    }

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event) {
        if (event.getActor() == client.getLocalPlayer()) {
            int hitsplatType = event.getHitsplat().getHitsplatType();
            if (hitsplatType == HitsplatID.POISON || hitsplatType == HitsplatID.VENOM) {
                ticksUntilDamage = POISON_TICK_RATE;
            }
        }
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        if (poisonValue > 0 && ticksUntilDamage > 0) {
            ticksUntilDamage--;
        }
    }

    public int getTicksUntilDamage() { return ticksUntilDamage; }
    public boolean isPoisoned() { 
        return poisonValue > 0 || config.testMode(); 
    }
    public boolean isVenom() { return isVenom; }
    public int getPoisonTickRate() { return POISON_TICK_RATE; }
}
